/**
 * MoveworksAPI — plain utility class, callable from widget server scripts,
 * business rules, and other server-side contexts.
 */
var MoveworksAPI = Class.create();
MoveworksAPI.prototype = {
    initialize: function() {},

    /**
     * Calls Anthropic Claude API and returns a JSON string of the Moveworks object.
     */
    callClaudeAPI: function(userRequest) {
        try {
            var rm = new sn_ws.RESTMessageV2('Moveworks Claude API', 'Build Object');

            var body = {
                model: 'claude-3-5-sonnet-20241022',
                max_tokens: 2048,
                system: 'You are a Moveworks object builder. Generate valid Moveworks JSON objects. Return only the tool call, no extra text.',
                tools: [{
                    name: 'build_moveworks_object',
                    description: 'Builds and returns a valid Moveworks object (Action, Event, or Slot) as structured JSON.',
                    input_schema: {
                        type: 'object',
                        properties: {
                            id: {
                                type: 'string',
                                description: 'Unique ID. Format: action.<name> | event.<name> | slot.<name>'
                            },
                            name: {
                                type: 'string',
                                description: 'Human readable name'
                            },
                            type: {
                                type: 'string',
                                enum: ['action', 'event', 'slot'],
                                description: 'Moveworks object type'
                            },
                            description: {
                                type: 'string',
                                description: 'What this object does (1-2 sentences)'
                            },
                            parameters: {
                                type: 'array',
                                description: 'Input parameters (for actions/events)',
                                items: {
                                    type: 'object',
                                    properties: {
                                        name:        { type: 'string' },
                                        type:        { type: 'string' },
                                        description: { type: 'string' },
                                        required:    { type: 'boolean' }
                                    }
                                }
                            },
                            output: {
                                type: 'object',
                                description: 'Output spec (for actions)',
                                properties: {
                                    type:        { type: 'string' },
                                    description: { type: 'string' }
                                }
                            },
                            trigger: {
                                type: 'string',
                                description: 'What triggers this event (for event objects)'
                            },
                            payload: {
                                type: 'array',
                                description: 'Payload fields (for event objects)',
                                items: {
                                    type: 'object',
                                    properties: {
                                        name:        { type: 'string' },
                                        type:        { type: 'string' },
                                        description: { type: 'string' }
                                    }
                                }
                            },
                            data_type: {
                                type: 'string',
                                description: 'Data type for slot objects'
                            },
                            required: {
                                type: 'boolean',
                                description: 'Whether this slot is required'
                            },
                            default_value: {
                                description: 'Default value for slot objects'
                            }
                        },
                        required: ['id', 'name', 'type', 'description']
                    }
                }],
                tool_choice: { type: 'tool', name: 'build_moveworks_object' },
                messages: [{
                    role: 'user',
                    content: this._buildPrompt(userRequest)
                }]
            };

            rm.setRequestBody(JSON.stringify(body));
            var response    = rm.execute();
            var statusCode  = response.getStatusCode();

            if (statusCode !== 200) {
                gs.error('MoveworksBuilder: Claude API returned status ' + statusCode + ' — ' + response.getBody());
                return JSON.stringify({ error: 'Claude API error: HTTP ' + statusCode });
            }

            var responseBody = JSON.parse(response.getBody());

            // Extract the tool_use block — contains the structured Moveworks object
            if (responseBody.content) {
                for (var i = 0; i < responseBody.content.length; i++) {
                    if (responseBody.content[i].type === 'tool_use') {
                        return JSON.stringify(responseBody.content[i].input);
                    }
                }
            }
            return JSON.stringify({ error: 'No tool_use block in Claude response' });

        } catch (e) {
            gs.error('MoveworksBuilder._callClaudeAPI: ' + e.message);
            return JSON.stringify({ error: e.message });
        }
    },

    /**
     * Builds an XML-structured prompt for Claude.
     */
    _buildPrompt: function(userRequest) {
        return [
            '<role>',
            '  You are a Moveworks object builder. Generate a valid Moveworks JSON object based on the request.',
            '</role>',
            '<guidelines>',
            '  1. Always include required fields: id, name, type, description',
            '  2. Use snake_case for all id values and parameter names',
            '  3. Prefix IDs correctly: action. / event. / slot.',
            '  4. For actions, always include parameters array and output block',
            '  5. For events, always include trigger and payload array',
            '  6. For slots, always include data_type and required fields',
            '</guidelines>',
            '<user_request>',
            userRequest,
            '</user_request>'
        ].join('\n');
    },

    type: 'MoveworksAPI'
};

/**
 * MoveworksBuilder — AbstractAjaxProcessor wrapper for GlideAjax calls
 * from the widget client script.
 */
var MoveworksBuilder = Class.create();
MoveworksBuilder.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * AJAX entry point — called from widget client script via GlideAjax.
     * sysparm_request : natural language request from the user
     * Returns JSON string of the generated Moveworks object.
     */
    buildObject: function() {
        var userRequest = this.getParameter('sysparm_request');
        if (!userRequest) {
            return JSON.stringify({ error: 'No request provided' });
        }
        var api = new x_146833_movewor_0.MoveworksAPI();
        return api.callClaudeAPI(userRequest);
    },

    type: 'MoveworksBuilder'
});
